    /**
     * One server-sent event: wire metadata plus the decoded {@code value} of its data;
     * {@code retry} is the server's reconnection time in milliseconds.
     */
    public record SseEvent<T>(String id, String event, String data, T value, Long retry) {}

    /**
     * Incrementally decoded {@code text/event-stream} response. Single-use: iterate it
     * (or call {@link #stream()}) exactly once and close it when done. Events are
     * dispatched on a blank line, {@code [DONE]} ends the stream, comment lines are
     * skipped, and an event still incomplete when a connection ends is discarded.
     * Every line is bounded by the client's {@code maxResponseBytes} and every event
     * by {@link StreamOptions#maxLineLength()}.
     *
     * <p>When a connection ends without {@code [DONE]} (the server closed it or a read
     * failed), the stream resumes at most {@link StreamOptions#maxReconnects()} times
     * (V3-785): {@link StreamOptions#onReconnect()} observes the resumption, the
     * stream waits {@link StreamOptions#reconnectDelay()} or the server's last
     * {@code retry}, and the request is sent again with the last event id seen as
     * {@code Last-Event-ID}, to the client's own origin only. A failed resumption
     * request, an exceeded bound or an undecodable event ends the stream with its
     * exception, and a closed stream never resumes.
     */
    public static final class SseStream<T> implements Iterable<SseEvent<T>>, AutoCloseable {
        private final Function<String, T> decoder;
        private final int maxEventBytes;
        private final String operationId;
        private final StreamOptions streamOptions;
        private final Function<String, CompletableFuture<HttpResponse<InputStream>>> replay;
        private final ByteArrayOutputStream line = new ByteArrayOutputStream();
        private volatile InputStream input;
        private volatile boolean done;
        private int statusCode;
        private Map<String, List<String>> headers;
        private String lastEventId;
        private Duration reconnectDelay;
        private int reconnects;
        private int eventBytes;
        private boolean iterated;
        private boolean pendingCarriageReturn;
        private boolean connectionStart;

        SseStream(HttpResponse<InputStream> response, Function<String, T> decoder, int maxEventBytes,
                String operationId) {
            this(response, decoder, maxEventBytes, operationId, StreamOptions.DEFAULT, null);
        }

        SseStream(HttpResponse<InputStream> response, Function<String, T> decoder, int maxEventBytes,
                String operationId, StreamOptions streamOptions,
                Function<String, CompletableFuture<HttpResponse<InputStream>>> replay) {
            this.decoder = decoder;
            this.maxEventBytes = maxEventBytes;
            this.operationId = operationId;
            this.streamOptions = Objects.requireNonNull(streamOptions, "streamOptions");
            this.replay = replay;
            this.lastEventId = streamOptions.lastEventId();
            this.reconnectDelay = streamOptions.reconnectDelay();
            adopt(response);
        }

        private void adopt(HttpResponse<InputStream> response) {
            input = response.body();
            statusCode = response.statusCode();
            headers = response.headers().map();
            eventBytes = 0;
            pendingCarriageReturn = false;
            connectionStart = true;
        }

        /** The status of the most recent response. */
        public int statusCode() { return statusCode; }
        /** The headers of the most recent response. */
        public Map<String, List<String>> headers() { return headers; }
        /** The most recent {@code id:} field of a dispatched event, for {@code Last-Event-ID} resumption. */
        public String lastEventId() { return lastEventId; }
        /** How many bounded resumptions this stream has made. */
        public int reconnects() { return reconnects; }

        @Override public Iterator<SseEvent<T>> iterator() {
            if (iterated) throw new IllegalStateException("SseStream can be iterated once");
            iterated = true;
            return new Iterator<>() {
                private SseEvent<T> next;
                @Override public boolean hasNext() {
                    if (next == null && !done) next = readEvent();
                    return next != null;
                }
                @Override public SseEvent<T> next() {
                    if (!hasNext()) throw new NoSuchElementException();
                    SseEvent<T> current = next;
                    next = null;
                    return current;
                }
            };
        }

        /** A sequential stream over the events; closing it closes the response. */
        public Stream<SseEvent<T>> stream() {
            return StreamSupport.stream(spliterator(), false).onClose(this::close);
        }

        /** Drain the remaining events into a list and close the response. */
        public List<SseEvent<T>> toList() {
            List<SseEvent<T>> events = new ArrayList<>();
            try (SseStream<T> self = this) {
                for (SseEvent<T> event : self) events.add(event);
            }
            return events;
        }

        @Override public void close() {
            done = true;
            try { input.close(); } catch (IOException ignored) { /* already closing */ }
        }

        private SseEvent<T> readEvent() {
            StringBuilder data = null;
            String event = null;
            String id = null;
            Long retry = null;
            while (true) {
                if (done) return null;
                String text;
                IOException failure = null;
                try { text = readLine(); }
                catch (IOException error) { text = null; failure = error; }
                if (text == null) {
                    // The connection ended: an event without its terminating blank line is
                    // discarded (WHATWG), and a bounded resumption may continue the stream.
                    if (done) return null;
                    boolean resumed;
                    try { resumed = resume(failure); }
                    catch (RuntimeException error) { close(); throw error; }
                    if (!resumed) {
                        close();
                        if (failure != null) throw new ApiTransportException(operationId, 1, failure);
                        return null;
                    }
                    data = null;
                    event = null;
                    id = null;
                    retry = null;
                    continue;
                }
                if (text.isEmpty()) {
                    eventBytes = 0;
                    if (id != null) lastEventId = id;
                    if (retry != null) {
                        reconnectDelay = Duration.ofMillis(Math.min(retry, StreamOptions.MAX_RECONNECT_DELAY.toMillis()));
                    }
                    if (data == null) { event = null; id = null; retry = null; continue; }
                    String payload = data.toString();
                    if (payload.equals("[DONE]")) { close(); return null; }
                    return new SseEvent<>(id, event, payload, decode(payload), retry);
                }
                if (text.charAt(0) == ':') continue;
                int colon = text.indexOf(':');
                String field = colon < 0 ? text : text.substring(0, colon);
                String value = colon < 0 ? "" : text.substring(colon + 1);
                if (value.startsWith(" ")) value = value.substring(1);
                switch (field) {
                    case "data" -> {
                        if (data == null) data = new StringBuilder(value);
                        else data.append('\n').append(value);
                    }
                    case "event" -> event = value;
                    case "id" -> { if (value.indexOf('\0') < 0) id = value; }
                    case "retry" -> {
                        Long parsed = parseRetry(value);
                        if (parsed != null) retry = parsed;
                    }
                    default -> { /* unknown fields are ignored per the specification */ }
                }
            }
        }

        /** The server's reconnection time: ASCII digits only, in milliseconds, saturating. */
        private static Long parseRetry(String value) {
            if (value.isEmpty()) return null;
            long result = 0L;
            for (int index = 0; index < value.length(); index++) {
                char ch = value.charAt(index);
                if (ch < '0' || ch > '9') return null;
                int digit = ch - '0';
                result = result > (Long.MAX_VALUE - digit) / 10 ? Long.MAX_VALUE : result * 10 + digit;
            }
            return result;
        }

        private T decode(String payload) {
            try { return decoder.apply(payload); }
            catch (JsonException error) {
                close();
                throw new StreamingException("undecodable server-sent event data", operationId, "sse",
                        error.getMessage(), error);
            }
        }

        /** Resume after a connection ended, within the budget; false when the stream is over. */
        private boolean resume(IOException failure) {
            try { input.close(); } catch (IOException ignored) { /* the connection already ended */ }
            if (done || replay == null || reconnects >= streamOptions.maxReconnects()) return false;
            reconnects++;
            Duration delay = reconnectDelay;
            Consumer<ReconnectContext> hook = streamOptions.onReconnect();
            if (hook != null) hook.accept(new ReconnectContext(operationId, reconnects, lastEventId, delay, failure));
            if (!delay.isZero()) {
                try { Thread.sleep(delay.toMillis()); }
                catch (InterruptedException interrupted) {
                    Thread.currentThread().interrupt();
                    throw new CancellationException("server-sent event stream interrupted: " + operationId);
                }
            }
            if (done) return false;
            adopt(await(replay.apply(lastEventId)));
            if (done) close();
            return true;
        }

        /** Next line without its terminator (LF, CR or CRLF); null when the connection ended. */
        private String readLine() throws IOException {
            line.reset();
            while (true) {
                int ch = input.read();
                if (ch < 0) {
                    // An unterminated last line belongs to an incomplete event.
                    pendingCarriageReturn = false;
                    return null;
                }
                if (pendingCarriageReturn) {
                    pendingCarriageReturn = false;
                    if (ch == '\n') continue;
                }
                if (ch == '\r' || ch == '\n') {
                    pendingCarriageReturn = ch == '\r';
                    return lineText();
                }
                if (line.size() >= maxEventBytes) {
                    close();
                    throw new ApiResponseTooLargeException(operationId, 1, line.size() + 1, maxEventBytes);
                }
                if (eventBytes + line.size() >= streamOptions.maxLineLength()) {
                    close();
                    throw new StreamingException("server-sent event exceeded maxLineLength", operationId, "sse",
                            streamOptions.maxLineLength(), null);
                }
                line.write(ch);
            }
        }

        private String lineText() {
            eventBytes += line.size();
            String text = line.toString(StandardCharsets.UTF_8);
            if (connectionStart) {
                connectionStart = false;
                if (!text.isEmpty() && text.charAt(0) == 0xFEFF) text = text.substring(1);
            }
            return text;
        }
    }

    /**
     * Incrementally decoded {@code application/x-ndjson} response (V3-785). Single-use:
     * iterate it (or call {@link #stream()}) exactly once and close it when done. Every
     * non-blank line, terminated by LF, CR or CRLF or left unterminated at the end, is
     * one JSON value, bounded by the client's {@code maxResponseBytes} and by
     * {@link StreamOptions#maxLineLength()}; an invalid line ends the stream with a
     * {@link StreamingException}. NDJSON never resumes.
     */
    public static final class NdjsonStream<T> implements Iterable<T>, AutoCloseable {
        private final InputStream input;
        private final Function<Object, T> decoder;
        private final int maxLineBytes;
        private final String operationId;
        private final int maxLineLength;
        private final int statusCode;
        private final Map<String, List<String>> headers;
        private final ByteArrayOutputStream line = new ByteArrayOutputStream();
        private volatile boolean done;
        private T value;
        private boolean iterated;
        private boolean pendingCarriageReturn;
        private boolean connectionStart = true;

        NdjsonStream(HttpResponse<InputStream> response, Function<Object, T> decoder, int maxLineBytes,
                String operationId, StreamOptions streamOptions) {
            this.input = response.body();
            this.decoder = decoder;
            this.maxLineBytes = maxLineBytes;
            this.operationId = operationId;
            this.maxLineLength = streamOptions.maxLineLength();
            this.statusCode = response.statusCode();
            this.headers = response.headers().map();
        }

        public int statusCode() { return statusCode; }
        public Map<String, List<String>> headers() { return headers; }

        @Override public Iterator<T> iterator() {
            if (iterated) throw new IllegalStateException("NdjsonStream can be iterated once");
            iterated = true;
            return new Iterator<>() {
                private boolean ready;
                @Override public boolean hasNext() {
                    if (!ready && !done) ready = readValue();
                    return ready;
                }
                @Override public T next() {
                    if (!hasNext()) throw new NoSuchElementException();
                    ready = false;
                    T current = value;
                    value = null;
                    return current;
                }
            };
        }

        /** A sequential stream over the values; closing it closes the response. */
        public Stream<T> stream() {
            return StreamSupport.stream(spliterator(), false).onClose(this::close);
        }

        /** Drain the remaining values into a list and close the response. */
        public List<T> toList() {
            List<T> values = new ArrayList<>();
            try (NdjsonStream<T> self = this) {
                for (T item : self) values.add(item);
            }
            return values;
        }

        @Override public void close() {
            done = true;
            try { input.close(); } catch (IOException ignored) { /* already closing */ }
        }

        private boolean readValue() {
            while (true) {
                if (done) return false;
                String text;
                try { text = readLine(); }
                catch (IOException error) {
                    if (done) return false;
                    close();
                    throw new ApiTransportException(operationId, 1, error);
                }
                if (text == null) { close(); return false; }
                if (text.isBlank()) continue;
                Object parsed;
                try { parsed = Json.parse(text); }
                catch (JsonException error) {
                    close();
                    throw new StreamingException("invalid NDJSON line", operationId, "ndjson", error.getMessage(), error);
                }
                try { value = decoder.apply(parsed); }
                catch (JsonException error) {
                    close();
                    throw new StreamingException("undecodable NDJSON value", operationId, "ndjson",
                            error.getMessage(), error);
                }
                return true;
            }
        }

        /** Next line without its terminator (LF, CR or CRLF); null at the end of the response. */
        private String readLine() throws IOException {
            line.reset();
            while (true) {
                int ch = input.read();
                if (ch < 0) {
                    pendingCarriageReturn = false;
                    return line.size() == 0 ? null : lineText();
                }
                if (pendingCarriageReturn) {
                    pendingCarriageReturn = false;
                    if (ch == '\n') continue;
                }
                if (ch == '\r' || ch == '\n') {
                    pendingCarriageReturn = ch == '\r';
                    return lineText();
                }
                if (line.size() >= maxLineBytes) {
                    close();
                    throw new ApiResponseTooLargeException(operationId, 1, line.size() + 1, maxLineBytes);
                }
                if (line.size() >= maxLineLength) {
                    close();
                    throw new StreamingException("NDJSON line exceeded maxLineLength", operationId, "ndjson",
                            maxLineLength, null);
                }
                line.write(ch);
            }
        }

        private String lineText() {
            String text = line.toString(StandardCharsets.UTF_8);
            if (connectionStart) {
                connectionStart = false;
                if (!text.isEmpty() && text.charAt(0) == 0xFEFF) text = text.substring(1);
            }
            return text;
        }
    }

